def get_bulk_data(self, uri):
    """Return the value of the data element retrieved via `uri` using
    the bulk data URI handler.

    Parameters
    ----------
    uri : str
        The "BulkDataURI" of the JSON representation of the data
        element.

    Returns
    -------
    The value returned by the bulk data URI handler.
    """
    handler = self.bulk_data_uri_handler
    if self._handler_takes_uri_only(handler):
        warnings.warn(
            'The bulk data URI handler should accept the tag, VR and '
            '"BulkDataURI" of the data element; support for handlers '
            'that only accept the "BulkDataURI" is deprecated and will '
            'be removed in a future version',
            DeprecationWarning
        )
        return handler(uri)
    return handler(self.tag, self.vr, uri)

@staticmethod
def _handler_takes_uri_only(handler):
    """Return ``True`` if `handler` is a callable accepting a single
    argument (the "BulkDataURI" only) rather than the tag, VR and
    "BulkDataURI".
    """
    try:
        parameters = list(inspect.signature(handler).parameters.values())
    except (TypeError, ValueError):
        # no signature available, assume the current (3 argument) form
        return False
    if any(p.kind == p.VAR_POSITIONAL for p in parameters):
        return False
    positional = [
        p for p in parameters
        if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
    ]
    return len(positional) == 1 and positional[0].default is p.empty

